'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

if (input.length === 0 || input[0] === undefined) {
  process.exit(0);
}

let p = 0;
const xi = input[p++];
const yi = input[p++];
const xf = input[p++];
const yf = input[p++];
const n = input[p++];

const rectangles = [];
const xs = [xi, xf];
const ys = [yi, yf];

for (let k = 0; k < n; k++) {
  const x1 = input[p++];
  const y1 = input[p++];
  const x2 = input[p++];
  const y2 = input[p++];
  rectangles.push([x1, y1, x2, y2]);
  xs.push(x1, x2);
  ys.push(y1, y2);
}

xs.sort((a, b) => a - b);
ys.sort((a, b) => a - b);

const unique = arr => arr.filter((v, i) => i === 0 || v !== arr[i - 1]);
const X = unique(xs);
const Y = unique(ys);
const nx = X.length;
const ny = Y.length;
const cx = nx - 1;
const cy = ny - 1;

const xIndex = new Map();
const yIndex = new Map();
for (let i = 0; i < nx; i++) xIndex.set(X[i], i);
for (let i = 0; i < ny; i++) yIndex.set(Y[i], i);

const diff = new Int32Array(nx * ny);
const indexedRects = [];

for (const [x1, y1, x2, y2] of rectangles) {
  const a = xIndex.get(x1);
  const b = xIndex.get(x2);
  const c = yIndex.get(y1);
  const d = yIndex.get(y2);
  indexedRects.push([a, c, b, d]);

  if (a < b && c < d) {
    diff[c * nx + a]++;
    diff[c * nx + b]--;
    diff[d * nx + a]--;
    diff[d * nx + b]++;
  }
}

for (let j = 0; j < ny; j++) {
  const row = j * nx;
  for (let i = 0; i < nx; i++) {
    const idx = row + i;
    let value = diff[idx];
    if (i > 0) value += diff[idx - 1];
    if (j > 0) value += diff[idx - nx];
    if (i > 0 && j > 0) value -= diff[idx - nx - 1];
    diff[idx] = value;
  }
}

const horizontalCovered = new Uint8Array(ny * cx);
const verticalCovered = new Uint8Array(cy * nx);

for (let j = 0; j < cy; j++) {
  for (let i = 0; i < cx; i++) {
    if (diff[j * nx + i] > 0) {
      horizontalCovered[j * cx + i] = 1;
      horizontalCovered[(j + 1) * cx + i] = 1;
      verticalCovered[j * nx + i] = 1;
      verticalCovered[j * nx + i + 1] = 1;
    }
  }
}

for (const [a, c, b, d] of indexedRects) {
  if (a === b && c < d) {
    for (let j = c; j < d; j++) {
      verticalCovered[j * nx + a] = 1;
    }
  } else if (c === d && a < b) {
    for (let i = a; i < b; i++) {
      horizontalCovered[c * cx + i] = 1;
    }
  }
}

const start = yIndex.get(yi) * nx + xIndex.get(xi);
const target = yIndex.get(yf) * nx + xIndex.get(xf);
const totalNodes = nx * ny;

const dist = new Int32Array(totalNodes);
dist.fill(0x3fffffff);
const position = new Int32Array(totalNodes);
position.fill(-1);
const heap = new Int32Array(totalNodes);
let heapSize = 0;

dist[start] = 0;
heap[heapSize] = start;
position[start] = heapSize++;

function decreaseKey(node, newDistance) {
  if (newDistance >= dist[node]) return;

  dist[node] = newDistance;
  let pos = position[node];
  if (pos === -2) return;

  if (pos === -1) {
    pos = heapSize++;
    heap[pos] = node;
    position[node] = pos;
  }

  while (pos > 0) {
    const parent = (pos - 1) >> 1;
    const parentNode = heap[parent];
    if (dist[parentNode] <= newDistance) break;
    heap[pos] = parentNode;
    position[parentNode] = pos;
    pos = parent;
  }

  heap[pos] = node;
  position[node] = pos;
}

while (heapSize > 0) {
  const node = heap[0];
  const last = heap[--heapSize];
  position[node] = -2;

  if (heapSize > 0) {
    let pos = 0;
    while (true) {
      const left = pos * 2 + 1;
      if (left >= heapSize) break;
      const right = left + 1;
      let child = left;
      if (right < heapSize && dist[heap[right]] < dist[heap[left]]) {
        child = right;
      }
      if (dist[last] <= dist[heap[child]]) break;
      heap[pos] = heap[child];
      position[heap[pos]] = pos;
      pos = child;
    }
    heap[pos] = last;
    position[last] = pos;
  }

  if (node === target) break;

  const j = Math.floor(node / nx);
  const i = node - j * nx;
  const currentDistance = dist[node];

  if (i > 0) {
    const edge = j * cx + i - 1;
    decreaseKey(node - 1, currentDistance + (horizontalCovered[edge] ? 0 : X[i] - X[i - 1]));
  }
  if (i + 1 < nx) {
    const edge = j * cx + i;
    decreaseKey(node + 1, currentDistance + (horizontalCovered[edge] ? 0 : X[i + 1] - X[i]));
  }
  if (j > 0) {
    const edge = (j - 1) * nx + i;
    decreaseKey(node - nx, currentDistance + (verticalCovered[edge] ? 0 : Y[j] - Y[j - 1]));
  }
  if (j + 1 < ny) {
    const edge = j * nx + i;
    decreaseKey(node + nx, currentDistance + (verticalCovered[edge] ? 0 : Y[j + 1] - Y[j]));
  }
}

